-- ShopTrack: 500 synthetic orders. No real customer or payment information.
-- MySQL 8.0+. Timestamps are UTC; the tax/shipping rules are fictional.
-- Creates a dedicated new database; does not delete existing databases.
-- If shoptrack_500 already exists, stop and inspect it before running this script.
create database shoptrack_500;
use shoptrack_500;
create table orders (id varchar(30) primary key, user_id varchar(30) not null, status varchar(20) not null, subtotal decimal(12,2) not null, tax decimal(12,2) not null, shipping decimal(12,2) not null, total decimal(12,2) not null, shipping_address json not null, created_at datetime not null, delivered_at datetime null, currency char(3) not null, data_origin varchar(100) not null) engine=InnoDB;
create table order_items (order_id varchar(30) not null, item_no int not null, sku varchar(80) not null, name varchar(150) not null, quantity int not null, unit_price decimal(12,2) not null, primary key(order_id, item_no), foreign key(order_id) references orders(id)) engine=InnoDB;
start transaction;
commit;
